import os

import pytest

from pages.user_authentication_page import UserAuthenticationPage

pytestmark = [pytest.mark.ui]


@pytest.mark.smoke
def test_tc_001_01_login_with_valid_username_and_password(page, base_url, runtime_options) -> None:
    """Login with valid username and password

    ID: TC-001-01 | Priority: High | Source: studio:REQ-001

    Requirement REQ-001; positive test (equivalence)

    Expected:
      - The user dashboard page is displayed

    Tags: positive
    """
    page_obj = UserAuthenticationPage(page, runtime_options["resilience_policy"])
    # Step 1: Navigate to /login
    page_obj.open(base_url, '/login')
    # Step 2: Enter 'valid_user' in the Username field
    page_obj.enter_username('valid_user')
    # Step 3: Enter '***' in the Password field
    page_obj.enter_password(os.environ.get("IHARMONY_TEST_PASSWORD", ""))
    # Step 4: Click the Login button
    page_obj.click_login_button()
    # Expected: The user dashboard page is displayed
    assert page_obj.is_dashboard_page_visible()
